A.concat(B).forEach(r=>{if(!seen.has(r.id)){seen.add(r.id);merged.push(r);}});
console.log(JSON.stringify({feature:'All Database Merger',sources:2,merged:merged.length,ids:merged.map(r=>r.id)}));

const archive=[{t:'Dark Mode'},{t:'TOTP Guide'}];
function driftCheck(rec){const dup=archive.some(a=>a.t.toLowerCase()===rec.t.toLowerCase());return {ok:!dup,errors:dup?['duplicate title']:[]};}
console.log(JSON.stringify({feature:'Drift-Check Sentinel',new_rec:driftCheck({t:'Qi2 Guide'}),dup_rec:driftCheck({t:'dark mode'})}));

const LADDER=['simple','compounded','complex'];
function rank(n){return LADDER[Math.min(LADDER.length-1,Math.floor(n/5))];}
console.log(JSON.stringify({feature:'Teach-Ladder Engine',records:[0,4,7,12].map(n=>({n,rank:rank(n)}))}));

const crypto=require('crypto');
const ledger=[];let prev='GENESIS';
function append(entry){const h=crypto.createHash('sha256').update(prev+entry).digest('hex').slice(0,12);ledger.push({entry,prev,h});prev=h;return h;}
append('assistant-built:features');append('assistant-built:features-signature');
console.log(JSON.stringify({feature:'Provenance Ledger',entries:ledger.length,chain_ok:ledger[1].prev===ledger[0].h}));

function standard10(q){const low=q.toLowerCase();
if(low.includes('find'))return 'archive lookup path';
if(low.includes('generate')||low.includes('make'))return 'generation path';
return 'conversational path';}
console.log(JSON.stringify({feature:'On-Device Standard 1.0',routes:['find me dark mode features','generate a foldable concept','hello'].map(standard10),key:'none needed'}));

