const HARD=10n**15n;
function plan(n){n=BigInt(n);if(n>HARD)return {ok:false};return {ok:true,cap:HARD.toString(),throttled:true};}
console.log(JSON.stringify({feature:'Boundless Generator Core',ask_5:plan(5),ask_too_many:plan(10n**16n)}));

const pairs=[['dark mode','Dark Mode (Signature take)'],['totp','TOTP (Signature take)']];
